import json

# خدمة محاكاة داخل التمرين (بدون إنترنت)
DB = {
    "/users": (200, '{"items": [{"id": 1, "name": "sara"}, {"id": 2, "name": "ali"}], "next": "/users?page=2"}'),
    "/users?page=2": (200, '{"items": [{"id": 3, "name": "nora"}], "next": null}'),
    "/secret": (401, '{"error": "unauthorized"}'),
    "/boom": (500, '{"error": "server"}'),
}

def fake_get(path):
    status, body = DB.get(path, (404, '{"error": "not found"}'))
    return status, json.loads(body)

def fetch(path):
    status, data = fake_get(path)
    if status == 200:
        return data
    if status == 401:
        raise PermissionError("unauthorized")
    if status == 404:
        raise LookupError("not found")
    raise RuntimeError("server error")

for p in ["/secret", "/nope", "/boom"]:
    try:
        fetch(p)
    except Exception as e:
        print(type(e).__name__)

from urllib.parse import urlencode

def build(path, **params):
    if not params:
        return path
    return path + "?" + urlencode(params)

